CREATE TABLE IF NOT EXISTS public.completion_log ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users ON DELETE CASCADE, entry_id UUID REFERENCES public.entries(id) ON DELETE SET NULL, title TEXT NOT NULL, month DATE NOT NULL DEFAULT date_trunc('month', (now() AT TIME ZONE 'utc'))::date, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now() ); GRANT SELECT, INSERT, UPDATE, DELETE ON public.completion_log TO authenticated; GRANT ALL ON public.completion_log TO service_role; ALTER TABLE public.completion_log ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Users manage their own completion log" ON public.completion_log; CREATE POLICY "Users manage their own completion log" ON public.completion_log FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id); CREATE INDEX IF NOT EXISTS completion_log_user_month_idx ON public.completion_log (user_id, month); DROP TRIGGER IF EXISTS completion_log_set_updated_at ON public.completion_log; CREATE TRIGGER completion_log_set_updated_at BEFORE UPDATE ON public.completion_log FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
